import{_ as i,o as t,c as e,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Crimson 2021-03-31","description":"","frontmatter":{"title":"Ceph Crimson 2021-03-31","date":"2021-03-31T00:00:00.000Z","updated":"2021-04-01T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","Bluefs","Rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","擦除编码","复制","快照","克隆","虚拟化","云计算","存储","测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_2021-03-31.md","filePath":"posts/2021/Ceph_Crimson_2021-03-31.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Crimson_2021-03-31.md"};function o(n,l,s,u,p,d){return t(),e("div",null,[...l[0]||(l[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>时间</strong>: 最近一周</li><li><strong>参与者</strong>: 团队成员</li><li><strong>主要议题</strong>: 技术问题讨论、代码测试、文档更新、项目进展</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>MBD测试问题</strong>:</p><ul><li>使用Sam的新PR进行MBD测试，但存在间歇性的segmentation fault问题。</li><li>尝试复现问题，但条件不明确，仍在追踪中。</li><li>阅读Sam的segmentation fault代码和journal代码，发现并修复了一个小问题。</li></ul></li><li><p><strong>FIO测试问题</strong>:</p><ul><li>设置较大的offset（例如50GB）时，FIO无法运行。</li><li>不确定是FIO问题还是其他代码问题，需要进一步调试和确认。</li></ul></li><li><p><strong>文档更新</strong>:</p><ul><li>继续更新上周提到的恢复文档，解决了几个问题，预计下周完成。</li><li>讨论了使用unique ptr或foreign ptr进行连接重构的问题，决定继续使用unique ptr，但保留未来切换到foreign ptr的可能性。</li></ul></li><li><p><strong>状态机更新</strong>:</p><ul><li>更新了经典SD的状态机，以匹配Queensland中的更改，已准备好提交。</li><li>计划阅读Erased在Queensland中的事务处理，以便后续使用。</li></ul></li><li><p><strong>逻辑扩展</strong>:</p><ul><li>开发了一种方案，将所有相关分配信息嵌入到LBA层，避免使用extent map。</li><li>正在实施中，虽然更复杂，但可以消除第二个映射。</li></ul></li><li><p><strong>Ceph存储问题</strong>:</p><ul><li>实现了C store中的get和set地址方法。</li><li>正在尝试实现read和write meta方法，并调查可能的Marx问题。</li></ul></li><li><p><strong>树级别环境不变性</strong>:</p><ul><li>解决了管理树级别环境不变性的问题，正在进行最后的子节点合并工作。</li><li>下一步将推进布局和阶段级别的实现。</li></ul></li><li><p><strong>C-star原生堆栈改进</strong>:</p><ul><li>注意到C-star原生堆栈的一些改进，主要涉及零拷贝传递和一些bug修复。</li></ul></li><li><p><strong>单元测试问题</strong>:</p><ul><li>解决了Jenkins中单元测试不完整的问题，通过添加步骤在检查作业中止时终止运行中的单元测试。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>继续使用unique ptr进行连接重构，但保留未来切换到foreign ptr的可能性。</li><li>解决Jenkins中单元测试不完整的问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续追踪和解决MBD测试中的segmentation fault问题。</li><li>进一步调试和确认FIO测试中的问题。</li><li>完成恢复文档的更新。</li><li>实施逻辑扩展方案，消除extent map的使用。</li><li>推进Ceph存储和树级别环境不变性的实现。</li><li>阅读Raft论文，准备下周讨论。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>下周将举行CTS会议，欢迎大家添加感兴趣的话题。</li></ul>',11)])])}const c=i(r,[["render",o]]);export{g as __pageData,c as default};
